// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor, bytes32 guessHash) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 2 ether);

        // Actor locks in a guess: block is recorded as current block + 1.
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance to exactly the recorded guess block.
        // The recorded block was block.number at lockInGuess + 1.
        // We locked at whatever block the prank call occurred in.
        // For a fresh test, lock happened in the current block, so recorded = block.number + 1.
        vm.roll(block.number + 1);

        // At exactly the recorded block, the reference must revert.
        // The mutant (>=) will succeed and reset the guess block to 0.
        bool reverted;
        vm.prank(actor);
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assertTrue(reverted);
    }
}
